#include "chip8.asm"

; Elementary cellular automaton
;
; A row of 64 cells, each dead (0) or alive (1). The next state of a cell
; depends on the cell itself and its two neighbours; the left neighbour of
; the first cell is the last cell and vice versa. The 8 possible
; neighbourhoods are numbered 4*left + 2*centre + right, and bit number k
; of the rule (Wolfram's numbering) is the new state for neighbourhood k.
;
; Every generation is drawn as one row of pixels, starting at the top, so
; the screen shows the first 32 generations.
;
; Generated by Claude Code, Nov 25, 2026

; ---- Settings ---------------------------------------------------------

rule = 90       ; 0-255. Try 30 (chaos), 90 (Sierpinski triangle),
                ;        110 (use seed = 63), 184 (traffic)
seed = 34       ; 0-63. Column of the single live cell in the first row

; -----------------------------------------------------------------------

width  = 64
height = 32

; Registers:
;   V0 ... load/store register
;   V1 ... x, the column of the current cell
;   V2 ... y, the row = the generation
;   V3, V4, V5 ... old states of the left, current and right cell
;   V6 ... old state of the first cell (right neighbour of the last one)
;   V7 ... number of the neighbourhood

main:
    LD V2, 0            ; y := 0

.row:
    LD I, cells + width - 1
    LD V0, [I]
    LD V3, V0           ; left := last cell (wrap around)
    LD I, cells
    LD V0, [I]
    LD V4, V0           ; current := first cell
    LD V6, V0           ; ... which is needed again at the end of the row
    LD V1, 0            ; x := 0

.cell:
    LD V5, V6           ; right := first cell,
    SNE V1, width - 1   ; which is correct in the last column only.
    JP .draw
    LD I, cells + 1     ; Otherwise
    ADD I, V1
    LD V0, [I]
    LD V5, V0           ; right := cells(x + 1)

.draw:
    LD I, dot
    SE V4, 0            ; If the current cell is alive,
    DRW V1, V2, 1       ; draw it at (x, y)

    LD V7, V3           ; Number of the neighbourhood,
    ADD V7, V7          ;   4*left + 2*current + right,
    ADD V7, V4          ; built by doubling (ADD Vx, Vx)
    ADD V7, V7
    ADD V7, V5

    LD I, table
    ADD I, V7
    LD V0, [I]          ; New state := table(neighbourhood)
    LD I, cells
    ADD I, V1
    LD [I], V0          ; Store it in place; the old state is still in V4

    LD V3, V4           ; Slide the window one cell to the right
    LD V4, V5
    ADD V1, 1           ; x := x + 1
    SE V1, width        ; End of the row?
    JP .cell

    ADD V2, 1           ; y := y + 1
    SE V2, height       ; Bottom of the screen?
    JP .row

.end:
    JP .end

; A single pixel
dot:
    #d8 0b10000000

; The first generation: one live cell in column `seed`
cells:
    #res seed
    #d8 1
    #res width - seed - 1

; New state for each of the 8 neighbourhoods. The assembler works this
; out from `rule`, so there is nothing to decode at run time.
table:
    #d8 (rule >> 0) & 1     ; 000
    #d8 (rule >> 1) & 1     ; 001
    #d8 (rule >> 2) & 1     ; 010
    #d8 (rule >> 3) & 1     ; 011
    #d8 (rule >> 4) & 1     ; 100
    #d8 (rule >> 5) & 1     ; 101
    #d8 (rule >> 6) & 1     ; 110
    #d8 (rule >> 7) & 1     ; 111
